-- Group achievements by competition and keep legacy rows for deterministic repair.
alter table public.athlete_achievements rename to athlete_achievements_legacy;
alter index public.athlete_achievements_public_idx rename to athlete_achievements_legacy_public_idx;
alter index public.athlete_achievements_source_idx rename to athlete_achievements_legacy_source_idx;
drop trigger if exists enforce_athlete_achievement_publication on public.athlete_achievements_legacy;
drop trigger if exists set_updated_at on public.athlete_achievements_legacy;
drop trigger if exists audit_admin_mutation on public.athlete_achievements_legacy;
drop policy if exists "Content editors manage athlete achievements" on public.athlete_achievements_legacy;
drop function if exists private.enforce_athlete_achievement_publication();
revoke all on public.athlete_achievements_legacy from public, anon, authenticated;

create table public.athlete_achievement_groups (
  id uuid primary key default gen_random_uuid(), athlete_id uuid not null references public.athletes(id) on delete restrict,
  achievement_type text not null check (achievement_type in ('national_podium', 'international_podium', 'international_participation', 'state_record')),
  title text not null check (btrim(title) <> '' and char_length(title) <= 180),
  competition_name text not null check (btrim(competition_name) <> '' and char_length(competition_name) <= 180),
  location text not null check (btrim(location) <> '' and char_length(location) <= 180), achieved_on date not null,
  publication_status public.publication_status not null default 'draft', published_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  check (publication_status in ('draft', 'published') and ((publication_status = 'published' and published_at is not null) or (publication_status = 'draft' and published_at is null)))
);
create table public.athlete_achievement_results (
  id uuid primary key default gen_random_uuid(), group_id uuid not null references public.athlete_achievement_groups(id) on delete cascade,
  event_definition_id uuid references public.event_definitions(id) on delete restrict,
  podium_place smallint check (podium_place is null or podium_place in (1, 2, 3)),
  participation_outcome text check (participation_outcome is null or participation_outcome in ('top_8', 'outstanding_participation')),
  record_id uuid references public.records(id) on delete restrict, legacy_event_label text, legacy_payload jsonb, legacy_source_identifier text,
  created_at timestamptz not null default now(),
  check ((event_definition_id is not null and legacy_event_label is null and legacy_payload is null and legacy_source_identifier is null) or (event_definition_id is null and btrim(coalesce(legacy_event_label, '')) <> '' and jsonb_typeof(legacy_payload) = 'object' and btrim(coalesce(legacy_source_identifier, '')) <> ''))
);
create unique index athlete_achievement_results_event_idx on public.athlete_achievement_results (group_id, event_definition_id) where event_definition_id is not null;
create index athlete_achievement_groups_athlete_idx on public.athlete_achievement_groups (athlete_id, achieved_on desc, id);
create index athlete_achievement_results_group_idx on public.athlete_achievement_results (group_id, created_at, id);

-- Each flat row becomes one draft group and one remediation child; no rows are merged.
insert into public.athlete_achievement_groups (id, athlete_id, achievement_type, title, competition_name, location, achieved_on)
select md5('asanda:achievement-group:' || legacy.id::text)::uuid, legacy.athlete_id,
  case legacy.achievement_type when 'national_podium' then 'national_podium' when 'international_medal' then 'international_podium' else 'international_participation' end,
  legacy.title, coalesce(nullif(btrim(legacy.competition_name), ''), 'Competencia no registrada'), 'Ubicación no registrada', coalesce(legacy.achieved_on, legacy.valid_from, legacy.created_at::date)
from public.athlete_achievements_legacy legacy;
insert into public.athlete_achievement_results (id, group_id, podium_place, legacy_event_label, legacy_payload, legacy_source_identifier)
select md5('asanda:achievement-result:' || legacy.id::text)::uuid, md5('asanda:achievement-group:' || legacy.id::text)::uuid,
  coalesce(legacy.place, case legacy.medal when 'gold' then 1 when 'silver' then 2 when 'bronze' then 3 end),
  coalesce(nullif(btrim(legacy.competition_name), ''), nullif(btrim(legacy.title), ''), legacy.id::text), to_jsonb(legacy), legacy.id::text
from public.athlete_achievements_legacy legacy;
alter table public.athlete_achievement_groups enable row level security;
alter table public.athlete_achievement_results enable row level security;
revoke all on public.athlete_achievement_groups, public.athlete_achievement_results from public, anon, authenticated;

create or replace function private.validate_achievement_children(requested_type text, requested_children jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if requested_children is null or jsonb_typeof(requested_children) <> 'array' or jsonb_array_length(requested_children) = 0 then raise exception 'Los logros requieren al menos un resultado.' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_to_recordset(requested_children) as c(event_definition_id uuid) where c.event_definition_id is not null group by c.event_definition_id having count(*) > 1) then raise exception 'Cada evento solo puede aparecer una vez por competencia.' using errcode = '23505'; end if;
  if exists (select 1 from jsonb_to_recordset(requested_children) as c(event_definition_id uuid, record_id uuid, legacy_event_label text, legacy_payload jsonb, legacy_source_identifier text) where c.event_definition_id is null and (btrim(coalesce(c.legacy_event_label, '')) = '' or jsonb_typeof(c.legacy_payload) <> 'object' or btrim(coalesce(c.legacy_source_identifier, '')) = '' or c.record_id is not null)) then raise exception 'El resultado legado necesita etiqueta, datos y referencia de origen.' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_to_recordset(requested_children) as c(event_definition_id uuid) where c.event_definition_id is not null and not exists (select 1 from public.event_definitions e join public.disciplines d on d.id = e.discipline_id where e.id = c.event_definition_id and d.code = 'swimming' and e.relay_size is null)) then raise exception 'El evento debe pertenecer al catálogo individual de natación.' using errcode = '23514'; end if;
  if requested_type in ('national_podium', 'international_podium') and exists (select 1 from jsonb_to_recordset(requested_children) as c(event_definition_id uuid, podium_place smallint, participation_outcome text, record_id uuid) where c.event_definition_id is not null and (c.podium_place is null or c.podium_place not in (1, 2, 3) or c.participation_outcome is not null or c.record_id is not null)) then raise exception 'Los podios requieren únicamente primer, segundo o tercer lugar.' using errcode = '23514'; end if;
  if requested_type = 'international_participation' and exists (select 1 from jsonb_to_recordset(requested_children) as c(event_definition_id uuid, podium_place smallint, participation_outcome text, record_id uuid) where c.event_definition_id is not null and (c.participation_outcome is null or c.participation_outcome not in ('top_8', 'outstanding_participation') or c.podium_place is not null or c.record_id is not null)) then raise exception 'La participación internacional requiere Top 8 o participación destacada.' using errcode = '23514'; end if;
  if requested_type = 'state_record' and exists (select 1 from jsonb_to_recordset(requested_children) as c(event_definition_id uuid, podium_place smallint, participation_outcome text, record_id uuid) where c.event_definition_id is not null and (c.record_id is null or c.podium_place is not null or c.participation_outcome is not null or not exists (select 1 from public.records r where r.id = c.record_id and r.scope_type = 'state' and r.event_definition_id = c.event_definition_id and r.publication_status = 'published' and r.published_at is not null))) then raise exception 'El récord estatal debe referenciar un récord oficial publicado del mismo evento.' using errcode = '23514'; end if;
end;
$$;

create or replace function public.save_athlete_achievement_group_draft(requested_group_id uuid, requested_athlete_id uuid, requested_achievement_type text, requested_title text, requested_competition_name text, requested_location text, requested_achieved_on date, requested_children jsonb)
returns table (group_id uuid, athlete_id uuid, publication_status public.publication_status) language plpgsql security definer set search_path = '' as $$
declare stored_group_id uuid := requested_group_id; existing_athlete_id uuid;
begin
  if not private.is_administrator() then raise exception 'ACHIEVEMENT_UNAUTHORIZED' using errcode = '42501'; end if;
  if requested_athlete_id is null or requested_achievement_type not in ('national_podium', 'international_podium', 'international_participation', 'state_record') or btrim(coalesce(requested_title, '')) = '' or btrim(coalesce(requested_competition_name, '')) = '' or btrim(coalesce(requested_location, '')) = '' or requested_achieved_on is null then raise exception 'Los datos generales de la competencia son obligatorios.' using errcode = '22023'; end if;
  if stored_group_id is not null then select g.athlete_id into existing_athlete_id from public.athlete_achievement_groups g where g.id = stored_group_id; if not found or existing_athlete_id <> requested_athlete_id then raise exception 'La competencia no pertenece al atleta.' using errcode = '42501'; end if; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('asanda:athlete-achievement-groups:' || requested_athlete_id::text, 0)); perform 1 from public.athletes where id = requested_athlete_id for update; if not found then raise exception 'El atleta no existe.' using errcode = 'P0002'; end if;
  if stored_group_id is not null then perform 1 from public.athlete_achievement_groups g where g.id = stored_group_id and g.athlete_id = requested_athlete_id for update; if not found then raise exception 'La competencia no existe.' using errcode = 'P0002'; end if; end if;
  if stored_group_id is null and (select count(*) from public.athlete_achievement_groups g where g.athlete_id = requested_athlete_id) >= 6 then raise exception 'El atleta ya tiene seis o más competencias; remediá los datos existentes antes de crear otra.' using errcode = '23514'; end if;
  perform private.validate_achievement_children(requested_achievement_type, requested_children);
  if stored_group_id is null then insert into public.athlete_achievement_groups (athlete_id, achievement_type, title, competition_name, location, achieved_on) values (requested_athlete_id, requested_achievement_type, btrim(requested_title), btrim(requested_competition_name), btrim(requested_location), requested_achieved_on) returning id into stored_group_id; else update public.athlete_achievement_groups set achievement_type = requested_achievement_type, title = btrim(requested_title), competition_name = btrim(requested_competition_name), location = btrim(requested_location), achieved_on = requested_achieved_on, publication_status = 'draft', published_at = null where id = stored_group_id; if not found then raise exception 'La competencia no existe.' using errcode = 'P0002'; end if; delete from public.athlete_achievement_results where group_id = stored_group_id; end if;
  insert into public.athlete_achievement_results (group_id, event_definition_id, podium_place, participation_outcome, record_id, legacy_event_label, legacy_payload, legacy_source_identifier) select stored_group_id, c.event_definition_id, c.podium_place, c.participation_outcome, c.record_id, c.legacy_event_label, c.legacy_payload, c.legacy_source_identifier from jsonb_to_recordset(requested_children) as c(event_definition_id uuid, podium_place smallint, participation_outcome text, record_id uuid, legacy_event_label text, legacy_payload jsonb, legacy_source_identifier text);
  return query select g.id, g.athlete_id, g.publication_status from public.athlete_achievement_groups g where g.id = stored_group_id;
end;
$$;

create or replace function public.publish_athlete_achievement_group(requested_group_id uuid)
returns table (group_id uuid, publication_status public.publication_status, published_at timestamptz) language plpgsql security definer set search_path = '' as $$
declare stored public.athlete_achievement_groups%rowtype; stored_athlete_id uuid; child_count integer;
begin
  if not private.is_administrator() then raise exception 'ACHIEVEMENT_UNAUTHORIZED' using errcode = '42501'; end if;
  select athlete_id into strict stored_athlete_id from public.athlete_achievement_groups where id = requested_group_id; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('asanda:athlete-achievement-groups:' || stored_athlete_id::text, 0)); select * into strict stored from public.athlete_achievement_groups where id = requested_group_id for update;
  if stored.publication_status = 'published' then raise exception 'La competencia ya está publicada.' using errcode = '22023'; end if; select count(*) into child_count from public.athlete_achievement_results r where r.group_id = stored.id; if child_count = 0 then raise exception 'La competencia requiere al menos un resultado.' using errcode = '22023'; end if;
  if exists (select 1 from public.athlete_achievement_results r left join public.event_definitions e on e.id = r.event_definition_id where r.group_id = stored.id and (r.event_definition_id is null or e.is_active is not true or not exists (select 1 from public.disciplines d where d.id = e.discipline_id and d.code = 'swimming' and d.is_active and e.relay_size is null))) then raise exception 'Hay resultados sin evento activo del catálogo; corregilos antes de publicar.' using errcode = '23514'; end if;
  if stored.achievement_type in ('national_podium', 'international_podium') and exists (select 1 from public.athlete_achievement_results r where r.group_id = stored.id and (r.podium_place is null or r.participation_outcome is not null or r.record_id is not null)) then raise exception 'Los resultados de podio no son válidos.' using errcode = '23514'; end if;
  if stored.achievement_type = 'international_participation' and exists (select 1 from public.athlete_achievement_results r where r.group_id = stored.id and (r.participation_outcome is null or r.participation_outcome not in ('top_8', 'outstanding_participation') or r.podium_place is not null or r.record_id is not null)) then raise exception 'Los resultados de participación no son válidos.' using errcode = '23514'; end if;
  if stored.achievement_type = 'state_record' and exists (select 1 from public.athlete_achievement_results r left join public.records record on record.id = r.record_id where r.group_id = stored.id and (r.record_id is null or r.podium_place is not null or r.participation_outcome is not null or record.id is null or record.scope_type <> 'state' or record.publication_status <> 'published' or record.published_at is null or record.published_at > now() or record.event_definition_id <> r.event_definition_id)) then raise exception 'El récord estatal debe seguir publicado y coincidir con su evento.' using errcode = '23514'; end if;
  if not exists (select 1 from public.athletes a where a.id = stored.athlete_id and a.publication_status = 'published' and private.has_active_consent(a.id, 'public_profile') and private.has_active_consent(a.id, 'results_publication')) then raise exception 'La publicación requiere un atleta publicado y ambos consentimientos de perfil y resultados.' using errcode = '23514'; end if;
  update public.athlete_achievement_groups as g set publication_status = 'published', published_at = now() where g.id = stored.id returning g.id, g.publication_status, g.published_at into group_id, publication_status, published_at; return next;
end;
$$;

create or replace function public.delete_athlete_achievement_group(requested_group_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$
declare stored_athlete_id uuid;
begin
  if not private.is_administrator() then raise exception 'ACHIEVEMENT_UNAUTHORIZED' using errcode = '42501'; end if; select athlete_id into strict stored_athlete_id from public.athlete_achievement_groups where id = requested_group_id; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('asanda:athlete-achievement-groups:' || stored_athlete_id::text, 0)); perform 1 from public.athlete_achievement_groups where id = requested_group_id for update; delete from public.athlete_achievement_groups where id = requested_group_id; return requested_group_id;
end;
$$;

create or replace function public.list_athlete_achievement_groups(requested_athlete_id uuid)
returns table (group_id uuid, athlete_id uuid, achievement_type text, title text, competition_name text, location text, achieved_on date, publication_status public.publication_status, published_at timestamptz, children jsonb) language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.is_administrator() then raise exception 'ACHIEVEMENT_UNAUTHORIZED' using errcode = '42501'; end if;
  return query select g.id, g.athlete_id, g.achievement_type, g.title, g.competition_name, g.location, g.achieved_on, g.publication_status, g.published_at, coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'event_definition_id', r.event_definition_id, 'event_name', e.name, 'event_active', e.is_active, 'podium_place', r.podium_place, 'participation_outcome', r.participation_outcome, 'record_id', r.record_id, 'record_status', record.publication_status, 'legacy_event_label', r.legacy_event_label, 'legacy_payload', r.legacy_payload, 'legacy_source_identifier', r.legacy_source_identifier) order by e.code nulls last, r.id) from public.athlete_achievement_results r left join public.event_definitions e on e.id = r.event_definition_id left join public.records record on record.id = r.record_id where r.group_id = g.id), '[]'::jsonb) from public.athlete_achievement_groups g where requested_athlete_id is null or g.athlete_id = requested_athlete_id order by g.achieved_on desc, g.id;
end;
$$;

create or replace function private.get_public_athlete_achievement_groups(requested_athlete_id uuid) returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(card order by achieved_on desc, group_id), '[]'::jsonb) from (select g.id group_id, g.achieved_on, jsonb_build_object('type', g.achievement_type, 'title', g.title, 'competitionName', g.competition_name, 'location', g.location, 'achievedOn', g.achieved_on, 'children', child.children) card from public.athlete_achievement_groups g cross join lateral (select count(*) filter (where valid) child_count, coalesce(jsonb_agg(jsonb_build_object('eventName', eligible.name, 'podiumPlace', eligible.podium_place, 'participationOutcome', eligible.participation_outcome, 'record', case when g.achievement_type = 'state_record' then jsonb_build_object('timeMs', eligible.time_ms, 'achievedYear', eligible.achieved_year, 'competitionName', eligible.competition_name_snapshot, 'categoryName', eligible.age_category_name_snapshot, 'competitiveSex', eligible.competitive_sex, 'course', eligible.course) end) order by eligible.code, eligible.id) filter (where valid), '[]'::jsonb) children from (select r.*, e.name, e.code, e.is_active, e.relay_size, e.discipline_id, record.scope_type, record.publication_status record_status, record.published_at record_published_at, record.event_definition_id record_event, record.time_ms, record.achieved_year, record.competition_name_snapshot, record.age_category_name_snapshot, record.competitive_sex, record.course, ((e.id is not null and e.is_active and e.relay_size is null and exists (select 1 from public.disciplines d where d.id = e.discipline_id and d.code = 'swimming' and d.is_active)) and ((g.achievement_type in ('national_podium', 'international_podium') and r.podium_place in (1, 2, 3) and r.participation_outcome is null and r.record_id is null) or (g.achievement_type = 'international_participation' and r.participation_outcome in ('top_8', 'outstanding_participation') and r.podium_place is null and r.record_id is null) or (g.achievement_type = 'state_record' and r.record_id is not null and r.podium_place is null and r.participation_outcome is null and record.scope_type = 'state' and record.publication_status = 'published' and record.published_at is not null and record.published_at <= now() and record.event_definition_id = r.event_definition_id))) valid from public.athlete_achievement_results r left join public.event_definitions e on e.id = r.event_definition_id left join public.records record on record.id = r.record_id where r.group_id = g.id) eligible) child where g.athlete_id = requested_athlete_id and g.publication_status = 'published' and g.published_at <= now() and child.child_count > 0 order by g.achieved_on desc, g.id limit 6) cards;
$$;

create or replace function private.get_featured_athlete_profiles(requested_limit integer, requested_offset integer)
returns table (profile_key text, display_order integer, display_name text, preferred_name text, photo_provider text, photo_public_id text, photo_external_url text, photo_alt_text text, club_name text, club_short_name text, category_name text, events jsonb, results jsonb, achievements jsonb) language plpgsql stable security definer set search_path = '' as $$
begin
  if requested_limit is null or requested_limit < 1 or requested_limit > 100 then raise exception 'Featured athlete profile limit must be between 1 and 100.' using errcode = '22023'; end if; if requested_offset is null or requested_offset < 0 then raise exception 'Featured athlete profile offset must be non-negative.' using errcode = '22023'; end if;
  return query with visible_featured as (select f.athlete_id, f.display_order from public.featured_athletes f where (f.starts_at is null or f.starts_at <= now()) and (f.ends_at is null or f.ends_at > now()) and private.is_featured_eligible_athlete(f.athlete_id) order by f.display_order limit requested_limit offset requested_offset), published_result_rows as (select entry.athlete_id, definition.name event_name, performance.time_ms, performance.place, competition.name competition_name, competition.starts_on competition_date from visible_featured f join public.entries entry on entry.athlete_id = f.athlete_id join public.performances performance on performance.entry_id = entry.id join public.source_documents document on document.id = performance.source_document_id and document.status = 'processed' and document.approval_status = 'approved' join public.competition_events ce on ce.id = entry.competition_event_id join public.competitions competition on competition.id = ce.competition_id join public.event_definitions definition on definition.id = ce.event_definition_id where performance.status = 'official' and competition.published_at is not null and competition.status in ('scheduled', 'in_progress', 'completed', 'postponed', 'cancelled') and ce.status <> 'cancelled') select 'v1_' || encode(extensions.digest('asanda:featured-athlete:v1:' || athlete.id::text, 'sha256'), 'hex'), featured.display_order, athlete.display_name, athlete.preferred_name, photo.provider, photo.public_id, photo.external_url, photo.alt_text, club.name, club.short_name, category.name, coalesce((select jsonb_agg(x.event_name order by x.event_name) from (select distinct p.event_name from published_result_rows p where p.athlete_id = athlete.id) x), '[]'::jsonb), coalesce((select jsonb_agg(to_jsonb(x) order by x.competition_date desc, x.event_name) from (select p.event_name, p.time_ms, p.place, p.competition_name, p.competition_date from published_result_rows p where p.athlete_id = athlete.id order by p.competition_date desc, p.event_name limit 8) x), '[]'::jsonb), private.get_public_athlete_achievement_groups(athlete.id) from visible_featured featured join public.athletes athlete on athlete.id = featured.athlete_id left join public.media_assets photo on photo.id = athlete.photo_asset_id and photo.is_public left join lateral (select o.name, o.short_name from public.athlete_memberships m join public.organizations o on o.id = m.organization_id where m.athlete_id = athlete.id and m.status = 'active' and m.valid_from <= current_date and (m.valid_to is null or m.valid_to >= current_date) and o.publication_status = 'published' order by o.id limit 1) club on true left join lateral (select c.name from public.athlete_category_assignments a join public.age_categories c on c.id = a.category_id where a.athlete_id = athlete.id and a.valid_from <= current_date and (a.valid_to is null or a.valid_to >= current_date) and c.is_active order by a.valid_from desc, c.sort_order desc limit 1) category on true order by featured.display_order;
end;
$$;

create trigger set_updated_at before update on public.athlete_achievement_groups for each row execute function private.set_updated_at();
create trigger audit_admin_mutation after insert or update or delete on public.athlete_achievement_groups for each row execute function private.capture_admin_audit();
create trigger audit_admin_mutation after insert or update or delete on public.athlete_achievement_results for each row execute function private.capture_admin_audit();
revoke all on function private.validate_achievement_children(text, jsonb), private.get_public_athlete_achievement_groups(uuid) from public, anon, authenticated;
revoke all on function public.save_athlete_achievement_group_draft(uuid, uuid, text, text, text, text, date, jsonb), public.publish_athlete_achievement_group(uuid), public.delete_athlete_achievement_group(uuid), public.list_athlete_achievement_groups(uuid) from public, anon, authenticated;
grant execute on function public.save_athlete_achievement_group_draft(uuid, uuid, text, text, text, text, date, jsonb), public.publish_athlete_achievement_group(uuid), public.delete_athlete_achievement_group(uuid), public.list_athlete_achievement_groups(uuid) to authenticated;
